//! Extraction-quality benchmark against hand-written ground truth (HLD §53
//! "Extraction" + "Semantic extraction").
//!
//! Corpus: `tests/fixtures/extraction-bench/` — generated by
//! `scripts/gen-extraction-bench-fixtures.py` and committed; each fixture has
//! a `<name>.gt.json` written by hand (never derived from an extractor).
//!
//! `holdout-entities.txt` was written after the M2 rules and never used to
//! tune them: `entity_*_holdout` is the honest generalisation estimate; the
//! other entity numbers are on text the rules were developed against.
//!
//! Metrics (all through the production chain: `extract_document` →
//! `document_model_to_ast` → `RuleBoundaryDetector` → `MockSemanticAnalyzer`):
//! - `entity_precision` / `entity_recall` — set match on (normalized text,
//!   type) pairs; predictions are every `EntityCandidate` (type_hint, `Thing`
//!   when untyped) plus every `TemporalAssertion` as `Date`. Scored on the
//!   analyzer IR, before the R8 secret filter redacts emails by policy.
//! - `table_cell_accuracy_pdf` / `_scan` — per gold table, the best
//!   predicted table on its page: cells equal at (row, col) over
//!   max(gold cells, predicted cells). Macro-averaged.
//! - `table_false_positives` — predicted tables on pages the gold says have
//!   none (two-column prose, letters). A ceiling, not a floor.
//! - `ocr_char_accuracy` — 1 − Levenshtein / gold length, whitespace
//!   collapsed and `|` table markup ignored.
//!
//! Ratchet: `results.json` holds the pre-improvement `baseline` (never
//! edited) and the `floor` each later milestone raises. A metric below its
//! floor (or false positives above the ceiling) fails. Cells whose tool is
//! missing (tesseract, pdftotext) skip with a note — the Linux CI job installs
//! poppler-utils (so the PDF table cell runs there) but not tesseract.

use aikoql_ingestion::{
    document_model_to_ast, document_model_to_ir, extract_document, tool_available, AstNode,
    AstPayload, MockSemanticAnalyzer, TablePayload,
};
use serde_json::Value;
use std::collections::{BTreeMap, HashSet};
use std::path::Path;

const DIR: &str = "tests/fixtures/extraction-bench";
const FIXTURES: &[&str] = &[
    "invoice.pdf",
    "entities.txt",
    "holdout-entities.txt",
    "scanned-table.png",
    "scanned-table-skewed.png",
    "scanned-letter.png",
];
const EPS: f64 = 0.005;

fn norm(s: &str) -> String {
    let collapsed = s.split_whitespace().collect::<Vec<_>>().join(" ");
    collapsed
        .trim_end_matches(['.', ',', ';', ':'])
        .to_lowercase()
}

fn levenshtein(a: &[char], b: &[char]) -> usize {
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    for (i, ca) in a.iter().enumerate() {
        let mut cur = vec![i + 1; b.len() + 1];
        for (j, cb) in b.iter().enumerate() {
            let sub = prev[j] + usize::from(ca != cb);
            cur[j + 1] = sub.min(prev[j + 1] + 1).min(cur[j] + 1);
        }
        prev = cur;
    }
    prev[b.len()]
}

fn ocr_accuracy(predicted: &str, gold: &str) -> f64 {
    let clean = |s: &str| -> Vec<char> {
        s.replace('|', " ")
            .split_whitespace()
            .collect::<Vec<_>>()
            .join(" ")
            .chars()
            .collect()
    };
    let (p, g) = (clean(predicted), clean(gold));
    if g.is_empty() {
        return 1.0;
    }
    (1.0 - levenshtein(&p, &g) as f64 / g.len() as f64).max(0.0)
}

/// Header row then body rows, cells in column order.
fn grid(t: &TablePayload) -> Vec<Vec<String>> {
    let mut rows = vec![t.headers.iter().map(|h| h.text.clone()).collect::<Vec<_>>()];
    for r in &t.rows {
        rows.push(
            t.cells
                .iter()
                .filter(|c| c.row_id == r.id)
                .map(|c| c.text.clone())
                .collect(),
        );
    }
    rows
}

fn tables_in(nodes: &[AstNode], out: &mut Vec<TablePayload>) {
    for n in nodes {
        if let Some(AstPayload::Table(t)) = &n.payload {
            out.push(t.clone());
        }
        tables_in(&n.children, out);
    }
}

fn cell_accuracy(pred: &[Vec<String>], gold: &[Vec<String>]) -> f64 {
    let count = |g: &[Vec<String>]| g.iter().map(|r| r.len()).sum::<usize>();
    let mut hit = 0usize;
    for (r, row) in gold.iter().enumerate() {
        for (c, cell) in row.iter().enumerate() {
            if pred
                .get(r)
                .and_then(|pr| pr.get(c))
                .is_some_and(|p| norm(p) == norm(cell))
            {
                hit += 1;
            }
        }
    }
    hit as f64 / count(gold).max(count(pred)).max(1) as f64
}

fn mean(v: &[f64]) -> Option<f64> {
    (!v.is_empty()).then(|| v.iter().sum::<f64>() / v.len() as f64)
}

/// Measured metrics; a metric is absent when its tool is missing.
fn measure() -> BTreeMap<&'static str, f64> {
    let has_tesseract = tool_available("tesseract");
    let has_pdftotext = tool_available("pdftotext");
    // [tuned corpus, held-out corpus] × (correct, predicted, gold).
    let mut ent = [[0usize; 3]; 2];
    let (mut pdf_cells, mut scan_cells, mut ocr) = (Vec::new(), Vec::new(), Vec::new());
    let mut false_tables = 0usize;

    for name in FIXTURES {
        let gt: Value = serde_json::from_str(
            &std::fs::read_to_string(Path::new(DIR).join(format!("{name}.gt.json"))).unwrap(),
        )
        .unwrap();
        let mime = gt["mime"].as_str().unwrap();
        if mime.starts_with("image/") && !has_tesseract {
            eprintln!("[XBENCH {name}] skipped: tesseract not on PATH");
            continue;
        }
        let path = Path::new(DIR).join(name);
        let dm = extract_document(&path.to_string_lossy(), mime, None)
            .unwrap_or_else(|e| panic!("{name}: {e}"));

        // Entities (typed).
        let gold: HashSet<(String, String)> = gt["entities"]
            .as_array()
            .unwrap()
            .iter()
            .map(|e| {
                (
                    norm(e["text"].as_str().unwrap()),
                    e["type"].as_str().unwrap().to_string(),
                )
            })
            .collect();
        if !gold.is_empty() {
            let ir = document_model_to_ir(&dm, &MockSemanticAnalyzer::new());
            let mut pred: HashSet<(String, String)> = ir
                .entities
                .iter()
                .map(|e| {
                    (
                        norm(&e.name),
                        e.type_hint.clone().unwrap_or_else(|| "Thing".into()),
                    )
                })
                .collect();
            pred.extend(ir.temporal.iter().map(|t| (norm(&t.text), "Date".into())));
            let hit = pred.intersection(&gold).count();
            let mut missed: Vec<_> = gold.difference(&pred).collect();
            missed.sort();
            let mut wrong: Vec<_> = pred.difference(&gold).collect();
            wrong.sort();
            eprintln!(
                "[XBENCH {name}] entities: predicted={} gold={} correct={hit}\n  missed={missed:?}\n  wrong={wrong:?}",
                pred.len(),
                gold.len()
            );
            let k = usize::from(gt["holdout"].as_bool() == Some(true));
            ent[k][0] += hit;
            ent[k][1] += pred.len();
            ent[k][2] += gold.len();
        }

        // Tables.
        let ast = document_model_to_ast(&dm);
        let page_tables = |page: usize| -> Vec<TablePayload> {
            let mut out = Vec::new();
            if let Some(p) = ast.pages.get(page.saturating_sub(1)) {
                tables_in(&p.children, &mut out);
            }
            out
        };
        for t in gt["tables"].as_array().unwrap() {
            let page = t["page"].as_u64().unwrap() as usize;
            let gold_rows: Vec<Vec<String>> = t["rows"]
                .as_array()
                .unwrap()
                .iter()
                .map(|r| {
                    r.as_array()
                        .unwrap()
                        .iter()
                        .map(|c| c.as_str().unwrap().to_string())
                        .collect()
                })
                .collect();
            let best = page_tables(page)
                .iter()
                .map(|p| cell_accuracy(&grid(p), &gold_rows))
                .fold(0.0f64, f64::max);
            eprintln!("[XBENCH {name}] table p{page}: cell accuracy {best:.3}");
            if mime.starts_with("image/") {
                scan_cells.push(best);
            } else if has_pdftotext {
                pdf_cells.push(best);
            } else {
                eprintln!("[XBENCH {name}] pdf table cell skipped: pdftotext not on PATH");
            }
        }
        for p in gt["no_table_pages"].as_array().unwrap() {
            let page = p.as_u64().unwrap() as usize;
            let n = page_tables(page).len();
            if n > 0 {
                eprintln!("[XBENCH {name}] page {page}: {n} false-positive table(s)");
            }
            false_tables += n;
        }

        // OCR.
        if let Some(gold_text) = gt["ocr_text"].as_str() {
            let text: Vec<&str> = dm.pages.iter().map(|p| p.text.as_str()).collect();
            let acc = ocr_accuracy(&text.join("\n"), gold_text);
            eprintln!("[XBENCH {name}] ocr char accuracy {acc:.3}");
            ocr.push(acc);
        }
    }

    let mut m = BTreeMap::new();
    for (k, (p, r)) in [
        ("entity_precision", "entity_recall"),
        ("entity_precision_holdout", "entity_recall_holdout"),
    ]
    .into_iter()
    .enumerate()
    {
        let [tp, n_pred, n_gold] = ent[k];
        if n_gold > 0 {
            m.insert(
                p,
                if n_pred == 0 {
                    1.0
                } else {
                    tp as f64 / n_pred as f64
                },
            );
            m.insert(r, tp as f64 / n_gold as f64);
        }
    }
    if let Some(v) = mean(&pdf_cells) {
        m.insert("table_cell_accuracy_pdf", v);
    }
    if let Some(v) = mean(&scan_cells) {
        m.insert("table_cell_accuracy_scan", v);
    }
    if let Some(v) = mean(&ocr) {
        m.insert("ocr_char_accuracy", v);
    }
    m.insert("table_false_positives", false_tables as f64);
    m
}

#[test]
fn levenshtein_and_cell_scorers_are_sane() {
    let c = |s: &str| s.chars().collect::<Vec<_>>();
    assert_eq!(levenshtein(&c("kitten"), &c("sitting")), 3);
    assert_eq!(ocr_accuracy("| a | b |", "a b"), 1.0);
    let g = vec![vec!["A".to_string(), "B".to_string()]];
    assert_eq!(cell_accuracy(&g, &g), 1.0);
    let shifted = vec![vec!["B".to_string()]];
    assert_eq!(cell_accuracy(&shifted, &g), 0.0);
    assert_eq!(norm("Acme Holdings Inc."), "acme holdings inc");
}

#[test]
fn extraction_quality_ratchet() {
    let measured = measure();
    let json = serde_json::to_string(&measured).unwrap();
    eprintln!("[XBENCH-JSON] {json}");

    let results: Value = serde_json::from_str(
        &std::fs::read_to_string(Path::new(DIR).join("results.json")).unwrap(),
    )
    .unwrap();
    let floor = results["floor"].as_object().unwrap();
    let mut failures = Vec::new();
    for (metric, f) in floor {
        let f = f.as_f64().unwrap();
        let Some(v) = measured.get(metric.as_str()) else {
            eprintln!("[XBENCH] {metric}: skipped (tool missing)");
            continue;
        };
        let ok = if metric == "table_false_positives" {
            *v <= f
        } else {
            *v + EPS >= f
        };
        eprintln!(
            "[XBENCH] {metric}: measured {v:.3} {} {f:.3}",
            if metric == "table_false_positives" {
                "ceiling"
            } else {
                "floor"
            }
        );
        if !ok {
            failures.push(format!("{metric}: measured {v:.3}, floor/ceiling {f:.3}"));
        }
    }
    assert!(
        failures.is_empty(),
        "extraction quality regressed: {failures:?}"
    );
}
